def have(a):
    out=set();off=0
    while True:
        r=factstore.query(f'select v from "{a}" order by v limit 1000 offset {off}').rows
        out|={x[0] for x in r}
        if len(r)<1000:return out
        off+=1000
orders=set();lines=set();cust=set()
for l in open('shopify/orders.jsonl'):
    d=json.loads(l);i=d['id'].split('/')[-1]
    if '/Order/' in d['id']:
        orders.add(i)
        if d.get('customer'): cust.add(d['customer']['id'].split('/')[-1])
    else: lines.add(i)
for a,s in [('shopify/order_id',orders),('shopify/line_item_id',lines),('shopify/customer_id',cust)]:
    h=have(a);print(a,len(s),'new',len(s-h),'gone',len(h-s))
al=set()
for r in csv.reader(open('amazon/all_orders.txt'),delimiter='\t'):
    if r[0]!='amazon-order-id': al.add(r[0]+'/'+r[10])
h=have('amazon/order_line');print('amz lines',len(al),'new',len(al-h),'gone',len(h-al))
tl=set(r['Tracking #']+'/'+r['Item Code'] for r in csv.DictReader(open('3pl/outbound.csv')))
h=have('tpl/outbound_line');print('tpl out',len(tl),len(tl-h),len(h-tl))
rl=set(r['Receipt #']+'/'+r['Item Code'] for r in csv.DictReader(open('3pl/receipts.csv')))
h=have('tpl/receipt_line');print('rcpt',len(rl),len(rl-h),len(h-rl))
f=set(r['Shipment ID'] for r in csv.DictReader(open('amazon/fba_inbound_shipments.csv')))
h=have('amazon/fba_shipment_id');print('fba',len(f),len(f-h),len(h-f))
E

